<template>
    <Encabezado titulo="Configurador de reportes" subtitulo="Dise&ntilde;o de reportes financieros por agrupaciones">
        <template #icono><font-icon icon="fa-solid fa-table-columns" /></template>
        <Button icon="pi pi-question-circle" text rounded aria-label="Gu&iacute;a del configurador" title="Gu&iacute;a del configurador" @click="mostrarAyuda = true" />
        <template v-if="editando"><Button label="Cancelar" icon="pi pi-times" severity="danger" :disabled="ocupado" @click="handleCancelar" /><Button label="Guardar" icon="pi pi-save" severity="success" :loading="guardando" :disabled="ocupado" @click="handleGuardar" /></template>
        <Button v-else label="Nuevo reporte" icon="pi pi-plus" :disabled="ocupado || !opciones.dimensiones.length" @click="handleNuevo" />
    </Encabezado>
    <div class="card configurador-reportes">
        <template v-if="!editando">
            <div class="barra-reportes"><Button label="Limpiar" icon="pi pi-filter-slash" outlined :disabled="ocupado" @click="handleLimpiar" /><InputText v-model="busqueda" placeholder="Buscar reporte..." :disabled="ocupado" /><Dropdown v-model="estado" :options="estados" optionLabel="label" optionValue="value" placeholder="Todos los estados" showClear :disabled="ocupado" /><Button label="Actualizar" icon="pi pi-refresh" outlined :disabled="ocupado" @click="handleActualizar" /><Tag :value="`${datos.length} reportes`" /></div>
            <DataTable :value="datos" :loading="cargando" paginator :rows="10" :rowsPerPageOptions="[10,25,50]" dataKey="_id" scrollable scrollHeight="55vh" class="tabla-encabezados tabla-reportes" :tableStyle="{width:'100%',tableLayout:'fixed'}">
                <template #empty>No hay reportes configurados.</template>
                <Column header="Reporte" style="width:27%"><template #body="{data}"><strong>{{ data.nombre }}</strong><small>{{ data.descripcion || 'Movimientos bancarios' }}</small></template></Column>
                <Column header="Filas" style="width:22%"><template #body="{data}">{{ data.modalidad === 'estado_resultados' ? 'Estado de resultados' : data.filas.map(handleEtiqueta).join(' / ') }}</template></Column>
                <Column header="Columnas" style="width:15%"><template #body="{data}">{{ data.modalidad === 'estado_resultados' ? 'Importe del periodo' : data.columnas.map(handleEtiqueta).join(' / ') || 'Sin agrupacion' }}</template></Column>
