                <Column header="Estado" style="width:9%"><template #body="{data}"><Tag :value="data.activo ? 'Activo' : 'Inactivo'" :severity="data.activo ? 'success' : 'secondary'" /></template></Column>
                <Column header="Opciones" style="width:6%"><template #body="{data}"><Button icon="pi pi-file-edit" severity="secondary" title="Editar reporte" aria-label="Editar reporte" :disabled="ocupado" @click="handleEditar(data)" /></template></Column>
            </DataTable>
        </template>
        <TabView v-else class="tabs-reporte">
            <TabPanel header="Datos"><div class="contenido-reporte"><Message v-if="errorFormulario" severity="error" :closable="false">{{ errorFormulario }}</Message><Fieldset legend="Datos del reporte"><div class="rejilla-reporte"><div class="campo"><label for="nombre-reporte">Nombre <span>*</span></label><InputText id="nombre-reporte" v-model="formulario.nombre" maxlength="100" :disabled="ocupado" placeholder="Ej. Egresos mensuales por concepto" /></div><div class="campo"><label>Modalidad</label><Select v-model="formulario.modalidad" :options="modalidades" optionLabel="label" optionValue="value" :disabled="ocupado" /></div><div class="campo"><label>Origen</label><InputText modelValue="Movimientos bancarios y conciliaciones CFDI" disabled /></div><div class="campo ancho-completo"><label for="descripcion-reporte">Descripci&oacute;n</label><Textarea id="descripcion-reporte" v-model="formulario.descripcion" rows="3" maxlength="500" :disabled="ocupado" /></div><div class="opcion-reporte"><InputSwitch inputId="activo-reporte" v-model="formulario.activo" :disabled="ocupado" /><label for="activo-reporte">Reporte activo</label></div></div></Fieldset><Message severity="info" :closable="false">Configura las agrupaciones y los valores en la pesta&ntilde;a Dise&ntilde;o. Esta pantalla guarda la configuraci&oacute;n; puedes consultarla con datos reales en Reportes / Reportes din&aacute;micos.</Message></div></TabPanel>
            <TabPanel header="Dise&ntilde;o"><div class="contenido-reporte"><div class="rejilla-reporte" v-if="formulario.modalidad !== 'estado_resultados'">
                <Fieldset legend="Filas"><div class="campo"><label>Agrupar por <span>*</span></label><MultiSelect v-model="formulario.filas" :options="dimensionesFilas" optionLabel="label" optionValue="value" display="chip" filter placeholder="Selecciona hasta 4 campos" :selectionLimit="4" :disabled="ocupado" /><small>El primer campo es la agrupaci&oacute;n principal.</small></div><div v-for="(campo, indice) in formulario.filas" :key="campo" class="orden-campo"><span><Tag :value="String(indice+1)" /> {{ handleEtiqueta(campo) }}</span><div><Button icon="pi pi-arrow-up" text aria-label="Subir agrupaci&oacute;n" :disabled="ocupado || indice === 0" @click="handleMover('filas', indice, -1)" /><Button icon="pi pi-arrow-down" text aria-label="Bajar agrupaci&oacute;n" :disabled="ocupado || indice === formulario.filas.length-1" @click="handleMover('filas', indice, 1)" /></div></div></Fieldset>
