                    <template v-if="renglon.tipo !== 'calculo'"><div class="opcion-reporte"><Checkbox v-model="renglon.todos_conceptos" binary :inputId="`todos-${renglon.id}`" :disabled="ocupado" /><label :for="`todos-${renglon.id}`">Incluir todos los conceptos de este tipo de movimiento</label></div><div v-if="!renglon.todos_conceptos" class="campo"><label>Conceptos incluidos (uno por l&iacute;nea)</label><Textarea :modelValue="renglon.conceptos_texto ?? renglon.conceptos.join('\n')" @update:modelValue="handleConceptosRenglon(renglon,$event)" rows="3" :disabled="ocupado" placeholder="Ej. NOMINA, utilizando una linea por concepto" /><small>Si dejas la lista vac&iacute;a, este renglon no incluir&aacute; movimientos. Asigna aqu&iacute; tus conceptos reales.</small></div></template>
                    <template v-else><div v-for="(termino,t) in renglon.terminos" :key="t" class="formula-estado"><Select v-model="termino.factor" :options="signos" optionLabel="label" optionValue="value" :disabled="ocupado" /><Select v-model="termino.renglon" :options="handleRenglonesAnteriores(indice)" optionLabel="label" optionValue="value" placeholder="Renglon anterior" :disabled="ocupado" /><Button icon="pi pi-times" text severity="danger" aria-label="Quitar termino" :disabled="ocupado" @click="renglon.terminos.splice(t,1)" /></div><Button label="Agregar suma o resta" icon="pi pi-plus" text :disabled="ocupado || indice === 0" @click="handleAgregarTermino(renglon)" /></template>
