            </div></div></TabPanel>
            <TabPanel header="Historial"><div class="contenido-reporte"><DataTable :value="[...(formulario.historial || [])].reverse()" paginator :rows="10" class="tabla-encabezados tabla-reportes"><template #empty>El historial se genera al guardar el reporte.</template><Column header="Fecha"><template #body="{data}">{{ handleFecha(data.fecha) }}</template></Column><Column field="usuario_nombre" header="Responsable" /><Column field="accion" header="Movimiento" /><Column header="Detalle"><template #body="{data}"><Button label="Ver cambios" icon="pi pi-history" outlined @click="handleCambios(data)" /></template></Column></DataTable></div></TabPanel>
        </TabView>
